public class MutableDateTime_addHours_TriageGen0Test {

    @Test
    public void testAddHours_Positive() {
        // Initial time: 2023-01-01T10:00:00.000
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        dt.addHours(5);
        // Expected: 2023-01-01T15:00:00.000
        Assert.assertEquals(15, dt.getHourOfDay());
        Assert.assertEquals(2023, dt.getYear());
        Assert.assertEquals(1, dt.getMonthOfYear());
        Assert.assertEquals(1, dt.getDayOfMonth());
    }














}

