public class MutableDateTime_addHours_TriageGen0Test {













    @Test
    public void testAddHours_LargeValue() {
        // Adding 24 * 365 hours (approx 1 year)
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);
        dt.addHours(24 * 365);
        // 2024 is a leap year, but adding exactly 365 days from Jan 1 2023 lands on Jan 1 2024
        Assert.assertEquals(2024, dt.getYear());
        Assert.assertEquals(1, dt.getMonthOfYear());
        Assert.assertEquals(1, dt.getDayOfMonth());
    }


}

